{
  "title": "祠堂之谜",
  "scene": "老宅的东侧是一处阴森的祠堂，门前的石狮子仿佛在诉说着古老的秘密。祠堂内布置古朴，但显得有些杂乱，供桌上的香灰已经有些许积尘，几幅泛黄的族谱挂于墙上，隐约可见家族的兴衰史。远处传来微弱的水声，似乎有水流经祠堂下方。玩家发现了几枚细微的线索：供桌下的地板似乎有些松动，一卷藏在族谱后面的旧报纸隐约可见，墙上的一幅壁画似乎暗示着家族的某种禁忌。",
  "goal": "找到祠堂内的隐秘机关，揭开家族的秘密。",
  "clue": "地板松动、旧报纸、壁画",
  "choices": [
    {"id": "A", "text": "检查供桌下的地板", "outcome": "地板下藏着一个小型的藏书阁，里面有一本旧日记，记录了家族在战乱时期的一些秘辛。", "result": "success", "next": "next_level"},
    {"id": "B", "text": "阅读墙上泛黄的族谱", "outcome": "族谱中夹着一张旧照片，照片后的空白处用墨水写有几句模糊的字迹，提示玩家寻找壁画上的线索。", "result": "partial", "next": "retry"},
    {"id": "C", "text": "观察壁画，尝试解读其含义", "outcome": "壁画描绘了一位被诅咒的家族祖先，壁画旁有几块脱落的砖石，玩家发现了一个暗门。", "result": "success", "next": "next_level"}
  ]
}
